/**
 * The self-custodial setup flow (PLAN §3.1, docs/decisions.md D-11), as library functions shared by
 * the `setup` CLI and the sandbox tests.
 *
 * Everything here is signed by the OWNER's own key, on the owner's machine:
 *   1. role accounts `agent-N.<owner>` and `executor-N.<owner>`, each created with exactly one
 *      function-call key (generated by the service itself; only its public key is passed in),
 *      scoped to the policy contract and that role's methods;
 *   2. the policy account, in ONE transaction: CreateAccount, Transfer, DeployContract,
 *      FunctionCall `new`. No access key is ever added to it;
 *   3. the treasury's storage registration on the token.
 * `verifySetup` then checks the result from chain state alone.
 *
 * v2 (docs/decisions.md D-28) costs about 1.4 NEAR in all on mainnet: ~0.86 NEAR of code
 * storage plus 0.2 NEAR for the contract's records, and the two role accounts.
 */
import { type Account, type Action, actions, baseDecode, type JsonRpcProvider, PublicKey } from "near-api-js";

import { sha256 } from "@noble/hashes/sha2.js";

import { bytesToHex } from "./bytes.ts";
import { PolicyView } from "./client.ts";
import { parseOutcome, type TxOutcome } from "./outcome.ts";
import type { Policy } from "./types.ts";
import { near, tgas } from "./units.ts";

export const AGENT_METHODS = ["propose"] as const;

export const EXECUTOR_METHODS = ["create_attempt", "fund", "forget"] as const;

/** NEP-145 registration cost on Circle USDC (min = max, docs/verified-facts.md). */
export const FT_STORAGE_DEPOSIT = 1_250_000_000_000_000_000_000n;

/** Storage staking: 1 NEAR per 100 kB (10^19 yocto per byte). */
const YOCTO_PER_BYTE = 10_000_000_000_000_000_000n;

export type RolePlan = {
  accountId: string;
  publicKey: string;
  /** NEAR sent to the role account, for gas. */
  balance: bigint;
  /** Function-call key allowance (gas the key may spend before rotation). */
  allowance: bigint;
};

export type SetupPlan = {
  ownerId: string;
  policyId: string;
  agent: RolePlan;
  executor: RolePlan;
  treasuryToken: string;
  treasuryDecimals: number;
  policy: Policy;
  wasm: Uint8Array;
  /** NEAR sent to the policy account (code + state storage, registrations). */
  policyBalance: bigint;
};

export function sha256Hex(bytes: Uint8Array): string {
  return bytesToHex(sha256(bytes));
}

/** Enough NEAR to stake the code's storage plus 0.2 NEAR for the contract's records (at most 50
 *  stored intents of ≈0.003 NEAR each, suppliers and kept invoice ids), rounded up to 0.05. */
export function suggestedPolicyBalance(wasmBytes: number): bigint {
  const step = near("0.05");
  const needed = BigInt(wasmBytes) * YOCTO_PER_BYTE + near("0.2");
  return ((needed + step - 1n) / step) * step;
}

/** The default policy for a first deployment: one tenth of v1's defaults (deploy/mainnet-policy.json). */
export const DEFAULT_POLICY: Policy = {
  autonomous_daily_budget: "5000000",
  approval_threshold: "2500000",
  daily_cap: "20000000",
  executor_trust_daily_budget: "0",
  cooldown_max: "500000",
  max_fixed_fee: "1500000",
  max_fee_bps: 100,
  cooldown_ns: "172800000000000",
  intent_ttl_ns: "259200000000000",
  quote_min_validity_ns: "300000000000",
  funding_margin_ns: "180000000000",
  callback_grace_ns: "3600000000000",
  retention_ns: "604800000000000",
  max_proposals_per_day: 20,
};

export function defaultRoleIds(ownerId: string, n = 1) {
  return {
    policyId: `getleash.${ownerId}`,
    agentId: `agent-${n}.${ownerId}`,
    executorId: `executor-${n}.${ownerId}`,
  };
}

export async function accountExists(rpc: JsonRpcProvider, accountId: string): Promise<boolean> {
  try {
    await rpc.viewAccount({ accountId });
    return true;
  } catch (error) {
    if (String((error as Error).message ?? error).match(/does not exist|UNKNOWN_ACCOUNT/i)) return false;
    throw error;
  }
}

async function send(owner: Account, receiverId: string, list: Action[]): Promise<TxOutcome> {
  const raw = await owner.signAndSendTransaction({ receiverId, actions: list, throwOnFailure: false });
  const outcome = parseOutcome(raw);
  if (!outcome.ok) {
    const reasons = outcome.failures.map((f) => f.panic ?? f.message).join("; ");
    throw new Error(`transaction to ${receiverId} failed: ${reasons} (tx ${outcome.txHash})`);
  }
  return outcome;
}

/** Creates `role.accountId` as a sub-account of the owner, holding only the role's function-call key. */
export function createRoleAccount(owner: Account, policyId: string, role: RolePlan, methods: readonly string[]) {
  if (!role.accountId.endsWith(`.${owner.accountId}`)) {
    throw new Error(`${role.accountId} is not a sub-account of ${owner.accountId}`);
  }
  return send(owner, role.accountId, [
    actions.createAccount(),
    actions.transfer(role.balance),
    actions.addFunctionCallAccessKey(PublicKey.fromString(role.publicKey), policyId, [...methods], role.allowance),
  ]);
}

/** The D-11 batch: the policy account is created, funded, deployed and initialised with no key. */
export function deployPolicy(owner: Account, plan: SetupPlan) {
  // Flat JSON, read by the contract's strict parser (contract/src/json.rs).
  const init = {
    owner_id: plan.ownerId,
    agent_id: plan.agent.accountId,
    executor_id: plan.executor.accountId,
    token_id: plan.treasuryToken,
    token_decimals: plan.treasuryDecimals,
    ...plan.policy,
  };
  return send(owner, plan.policyId, [
    actions.createAccount(),
    actions.transfer(plan.policyBalance),
    actions.deployContract(plan.wasm),
    actions.functionCall("new", init, tgas(100), 0n),
  ]);
}

/** Registers the policy account on the treasury token, paid by the owner. */
export function registerTreasury(owner: Account, plan: Pick<SetupPlan, "treasuryToken" | "policyId">) {
  return send(owner, plan.treasuryToken, [
    actions.functionCall(
      "storage_deposit",
      { account_id: plan.policyId, registration_only: true },
      tgas(30),
      FT_STORAGE_DEPOSIT,
    ),
  ]);
}

/** Owner top-up: a plain `ft_transfer` (v2 keeps no ledger; the balance is the token's). */
export function topUp(owner: Account, plan: Pick<SetupPlan, "treasuryToken" | "policyId">, amount: bigint) {
  return send(owner, plan.treasuryToken, [
    actions.functionCall("ft_transfer", { receiver_id: plan.policyId, amount: amount.toString() }, tgas(30), 1n),
  ]);
}

/** Registers a native supplier's account on the treasury token, paid by the owner (the contract
 *  pays a native transfer only to a registered account). */
export function registerOnToken(owner: Account, token: string, accountId: string) {
  return send(owner, token, [
    actions.functionCall("storage_deposit", { account_id: accountId, registration_only: true }, tgas(30), FT_STORAGE_DEPOSIT),
  ]);
}

// ── Verification from chain state ────────────────────────────────────────────────────────────

export type Check = { name: string; ok: boolean; detail: string };

type KeyView = {
  public_key: string;
  access_key: { permission: unknown };
};

function describePermission(permission: unknown): string {
  if (permission === "FullAccess") return "FULL ACCESS";
  const fc = (permission as { FunctionCall?: { receiver_id: string; method_names: string[] } }).FunctionCall;
  return fc ? `function-call → ${fc.receiver_id} [${fc.method_names.join(", ")}]` : JSON.stringify(permission);
}

async function keysOf(rpc: JsonRpcProvider, accountId: string): Promise<KeyView[]> {
  const list = (await rpc.viewAccessKeyList({ accountId })) as unknown as { keys: KeyView[] };
  return list.keys;
}

function sameMethods(a: readonly string[], b: readonly string[]) {
  return a.length === b.length && [...a].sort().join() === [...b].sort().join();
}

async function checkRole(
  rpc: JsonRpcProvider,
  role: Pick<RolePlan, "accountId" | "publicKey">,
  policyId: string,
  methods: readonly string[],
): Promise<Check> {
  const keys = await keysOf(rpc, role.accountId);
  const described = keys.map((k) => `${k.public_key}: ${describePermission(k.access_key.permission)}`);
  const ok =
    keys.length === 1 &&
    keys[0]!.public_key === role.publicKey &&
    (() => {
      const fc = (keys[0]!.access_key.permission as { FunctionCall?: { receiver_id: string; method_names: string[] } })
        .FunctionCall;
      return !!fc && fc.receiver_id === policyId && sameMethods(fc.method_names, methods);
    })();
  return { name: `${role.accountId} holds only its function-call key`, ok, detail: described.join(" | ") || "no keys" };
}

export async function verifySetup(
  rpc: JsonRpcProvider,
  plan: Pick<SetupPlan, "ownerId" | "policyId" | "agent" | "executor" | "treasuryToken"> & {
    wasmSha256?: string;
  },
): Promise<Check[]> {
  const checks: Check[] = [];
  const policyKeys = await keysOf(rpc, plan.policyId);
  checks.push({
    name: `${plan.policyId} has no access keys`,
    ok: policyKeys.length === 0,
    detail: policyKeys.length === 0 ? "0 keys" : policyKeys.map((k) => k.public_key).join(", "),
  });

  if (plan.wasmSha256) {
    const account = (await rpc.viewAccount({ accountId: plan.policyId })) as unknown as { code_hash: string };
    const onChain = bytesToHex(baseDecode(account.code_hash));
    checks.push({
      name: "deployed code matches the wasm",
      ok: onChain === plan.wasmSha256,
      detail: `on-chain sha256 ${onChain}`,
    });
  }

  const state = await new PolicyView(rpc, plan.policyId).state();
  const roles: Array<[string, string, string]> = [
    ["owner", state.owner_id, plan.ownerId],
    ["agent", state.agent_id, plan.agent.accountId],
    ["executor", state.executor_id, plan.executor.accountId],
    ["treasury token", state.token_id, plan.treasuryToken],
  ];
  for (const [label, actual, expected] of roles) {
    checks.push({ name: `contract ${label} is ${expected}`, ok: actual === expected, detail: actual });
  }
  checks.push({
    name: "executor trust budget",
    ok: true,
    detail: `${state.policy.executor_trust_daily_budget} per day without the owner (0 = every cross-chain payment owner-signed)`,
  });

  checks.push(await checkRole(rpc, plan.agent, plan.policyId, AGENT_METHODS));
  checks.push(await checkRole(rpc, plan.executor, plan.policyId, EXECUTOR_METHODS));
  return checks;
}
